export const narrativeKinds={linear:'顺叙',flashback:'倒叙',insert:'插叙',background:'背景事件'};
export const relationKinds={other:'其他',family:'亲属',partner:'伙伴',enemy:'敌对',mentor:'师生',affiliation:'归属'};
export const relationColors={other:'#8a94a6',family:'#b882da',partner:'#438fbf',enemy:'#d56c75',mentor:'#c99740',affiliation:'#42a592'};
