const emptyEvent=order=>({title:'',storyTime:'',order,narrativeKind:'linear',content:'',chapterRefs:[],memoryRefs:[],planningRefs:[],foreshadowRefs:[],revision:0});
export function Timeline({integrated=false,call,novelId,tick,run,busy,onChapter,onMemory,onPlanning,onForeshadow,onCreateMemory,planningItems,creationDefaults,onChanged,timelineControls,creationRequest,onCreationConsumed,foreshadowSelection}){
 const modules=useModules();
 const [placement,setPlacement]=usePreference(`${novelId}:event-placement-draft`,null),[placementOpen,setPlacementOpen]=useState(false),{confirm}=useDialog();

 const [localFocusShadow,setLocalFocusShadow]=usePreference(`${novelId}:foreshadow-selected`,null);
 const focusShadow=foreshadowSelection?foreshadowSelection.value:localFocusShadow,setFocusShadow=foreshadowSelection?.change||setLocalFocusShadow;
 const [createRequested,setCreateRequested]=usePreference(`${novelId}:timeline-create`,false),[newContext,setNewContext]=usePreference(`${novelId}:timeline-new-context`,null),[selected,setSelected]=usePreference(`${novelId}:timeline-event`,null),[creating,setCreating]=useState(false),[poll,setPoll]=useState(0),[relation,setRelation]=useState(null),[includeDeleted,setIncludeDeleted]=useState(false);
 useEffect(()=>{if(createRequested){setCreating(true);setCreateRequested(false);}},[createRequested]);
 const resource=useBoard(call,novelId,tick+poll,includeDeleted),details=useResource(()=>selected?call('writing.event.get',{novelId,id:selected}):Promise.resolve(null),[call,novelId,selected,tick,poll],`${novelId}:event:${selected}`);
 const refresh=()=>{setPoll(n=>n+1);onChanged?.();},close=()=>{setSelected(null);setCreating(false);setNewContext(null);};
 const autoPlace=useEventPlacement(call,novelId,refresh),place=autoPlace.place;
 const projected=autoPlace.project(resource.value),board=projected&&planningItems?{...projected,planning:planningItems}:projected,events=board?.events||[],chapters=board?.chapters||[],nodes=board?.nodes||[],plans=board?.planning||[],foreshadows=board?.foreshadows||[];
 const selectEvent=async(id,create)=>{if(!await autoPlace.flush())return;if(create){setSelected(null);setNewContext(typeof create==='object'?create:null);setCreating(true);}else setSelected(id);};
 useEffect(()=>{if(creationRequest?.kind==='event'){setSelected(null);setNewContext(null);setCreating(true);}else if(creationRequest?.kind==='foreshadow')setFocusShadow('new');if(creationRequest)onCreationConsumed?.();},[creationRequest?.id]);
 return <div className="structure-page timeline-page">{!integrated&&<div className="row"><h2 className="grow">时间线</h2><button className="primary" disabled={busy||!board} onClick={()=>selectEvent(null,true)}>＋ 事件</button></div>}{placement&&!placementOpen&&<div className="placement-draft-strip"><span>事件位置草稿 · {placement.source.title}</span><button onClick={()=>setPlacementOpen(true)}>继续调整</button><button disabled={busy} onClick={async()=>{if(await confirm('丢弃这份未保存的位置草稿？'))setPlacement(null);}}>丢弃</button></div>}{autoPlace.jobs.length>0&&<div className="placement-draft-strip" role={autoPlace.error?'alert':undefined}><span>{autoPlace.error||'位置正在后台保存…'}</span>{autoPlace.error&&<><button disabled={autoPlace.saving} onClick={autoPlace.retry}>重试保存</button><button disabled={autoPlace.saving} onClick={async()=>{if(await confirm('放弃未保存的位置调整，重新读取云端位置？')){autoPlace.discard();refresh();}}}>放弃位置草稿</button></>}</div>}<ResourceState resource={resource}>{board&&<StoryStage {...{board,call,novelId,run,busy,onChapter,onMemory,onPlanning,onForeshadow,onCreateMemory,refresh,creationDefaults}} controls={timelineControls} onPlace={place} onEvent={selectEvent} onRelation={(edge,event)=>{const previous=board.relationshipChanges.find(c=>!c.deleted&&c.edgeId===edge.id&&c.eventId===event?.id);setRelation(previous||{edgeId:edge.id,eventId:event?.id||'',value:{name:edge.name||'',content:edge.content||'',category:edge.category||'other',style:edge.style||'solid',active:true},revision:0});}}/>}</ResourceState>
 <details><summary>事件与关系历史 / 恢复</summary><label><input type="checkbox" checked={includeDeleted} onChange={e=>setIncludeDeleted(e.target.checked)}/> 显示已移除事件与关系变化</label>{events.map(e=><p key={e.id}><button onClick={()=>setSelected(e.id)}>{e.deleted?'已移除 · ':''}{e.title}</button></p>)}{board?.edges.map(e=><p key={e.id}><button onClick={()=>setRelation({edgeId:e.id,eventId:'',value:{name:e.name||'',content:e.content||'',category:e.category||'other',style:e.style||'solid',active:true},revision:0})}>记录关系变化：{nodes.find(n=>n.id===e.from)?.name} → {nodes.find(n=>n.id===e.to)?.name}</button></p>)}{board?.relationshipChanges.map(c=><p key={c.id}><button onClick={()=>setRelation(c)}>{c.deleted?'已移除 · ':''}{c.eventTitle} · {c.value.name||'关系结束'} · 编辑与历史</button></p>)}</details>
 {(creating||selected)&&<ResourceState resource={creating?resource:details}>{board&&(creating||details.value)&&<EventEditor key={selected||'new'} {...{call,novelId,busy,run,chapters,nodes,plans,foreshadows}} initial={creating?{...emptyEvent(Math.max(0,...events.map(e=>e.order))+10),...newContext,revision:0,enteringRefs:[],...(newContext?.chapterId?{chapterRefs:[{chapterId:newContext.chapterId,revision:newContext.revision,evidence:''}]}:{})}:details.value} close={close} latest={details.value} saved={()=>{close();refresh();}}/>}</ResourceState>}
 {placement&&placementOpen&&<EventPlacementEditor key={placement.id+placement.view} request={placement} change={setPlacement} {...{call,novelId,run,busy}} close={()=>setPlacementOpen(false)} saved={()=>{setPlacement(null);setPlacementOpen(false);refresh();}}/>}
 {modules.foreshadow&&focusShadow&&board&&<ShadowEditorLoader id={focusShadow==='new'?null:focusShadow} {...{call,novelId,board,run,busy}} chapter={chapters.find(c=>c.id===foreshadows.find(f=>f.id===focusShadow)?.firstPlantChapterId)} close={()=>setFocusShadow(null)} saved={()=>{setFocusShadow(null);refresh();}}/>}
 {modules.evolution&&relation&&board&&<ChangeEditor key={relation.id||relation.edgeId+relation.eventId} {...{call,novelId,busy,run,events,nodes}} edges={board.edges} initial={relation} close={()=>setRelation(null)} saved={()=>{setRelation(null);refresh();}}/>}</div>;
}
/** 关联资料统一用搜索式胶囊选择器：已关联显示头像胶囊，输入即搜、点结果即可加入。 */
function PickReferences({label,items,value,change,name='name'}){
 const list=Array.isArray(items)?items:[],chosenIds=Array.isArray(value)?value:[],[query,setQuery]=useState('');
 const labelOf=item=>String(item?.[name]||'').trim()||'未命名';
 const face=item=><span className={`pick-ref-face cast-tone tone-${castTone(labelOf(item))}`}>{item.avatarImage?<img src={item.avatarImage} alt=""/>:labelOf(item).slice(0,1)}</span>;
 const chosen=list.filter(item=>chosenIds.includes(item.id)),q=query.trim().toLowerCase();
 const available=list.filter(item=>!chosenIds.includes(item.id)&&(!q||labelOf(item).toLowerCase().includes(q)||String(item.summary||'').toLowerCase().includes(q))).slice(0,12);
 return <section className="pick-refs">
  <header><h3>{label}</h3><small>已关联 {chosenIds.length}</small></header>
  <div className="pick-refs-chosen">{chosen.length?chosen.map(item=><span className="pick-ref-pill" key={item.id}>{face(item)}<span className="pick-ref-name">{labelOf(item)}</span><button type="button" aria-label={`移除 ${labelOf(item)}`} onClick={()=>change(chosenIds.filter(id=>id!==item.id))}>×</button></span>):<p className="muted">还没有关联</p>}</div>
  <input className="pick-refs-search" aria-label={`搜索${label}`} placeholder="搜索名称并添加…" value={query} onChange={e=>setQuery(e.target.value)}/>
  {q&&<div className="pick-refs-results">{available.map(item=><button type="button" key={item.id} onClick={()=>{change([...chosenIds,item.id]);setQuery('');}}>{face(item)}{labelOf(item)}</button>)}{!available.length&&<p className="muted">没有匹配条目</p>}</div>}
 </section>;
}
function EventEditor({call,novelId,busy,run,initial,latest,chapters,nodes,plans,foreshadows,close,saved}){
 const modules=useModules();
 const write=useWritingRequest(call),{confirm}=useDialog(),{value:v,base,dirty,change,accept,cacheError}=useDraft(`${novelId}:event:${initial.id||'new'}`,initial),[chapterId,setChapterId]=useState(''),[quote,setQuote]=useState(''),[error,setError]=useState('');
 useEffect(()=>{if(!dirty&&latest?.revision>base.revision)accept(latest);},[latest,dirty]);
 const set=(key,value)=>change(old=>({...old,[key]:value}));
 const save=()=>run(async()=>{setError('');try{const result=await write(initial.id?'writing.event.update':'writing.event.create',{novelId,id:initial.id,expectedRevision:base.revision,value:{...v,title:v.title.trim()||'未命名事件'},confirmed:true,reason:'作者保存故事事件'});accept(initial.id?result:initial);saved();}catch(e){setError(e.message);throw e;}});
 return <Modal title={initial.id?"编辑事件":"新建事件"} close={close} className="chapter-materials-modal"><ReferenceButton reference={{kind:'event',novelId,id:initial.id,title:v.title,revision:base.revision,dirty}}/><div className="structure-form">{initial.deleted&&<p className="notice">此事件已移出时间线，可从历史恢复。</p>}{latest?.revision!==base.revision&&dirty&&<p className="notice">事件已有新版本，草稿保留，保存会检查冲突。</p>}<label>事件名称<input aria-label="事件名称" placeholder="未命名事件（可稍后补充）" value={v.title} onChange={e=>set('title',e.target.value)}/></label><label>故事时间<input aria-label="故事时间" placeholder="如：1991 年夏／入学前一晚" value={v.storyTime} onChange={e=>set('storyTime',e.target.value)}/></label><label>明确日期（可选）<input aria-label="故事日期" type="date" value={v.storyDate||''} onChange={e=>set('storyDate',e.target.value)}/></label><label>计划卷章（尚无正文时）<input aria-label="计划卷章" placeholder="如：第二卷 · 第三章" value={v.plannedChapter||''} onChange={e=>set('plannedChapter',e.target.value)}/></label>{!v.chapterRefs.some(r=>chapters.some(c=>c.id===r.chapterId))&&<label>待写叙述排序<input aria-label="待写叙述排序" type="number" value={v.narrationOrder??''} onChange={e=>set('narrationOrder',e.target.value===''?null:Number(e.target.value))}/></label>}<p className="muted">关联正文后，各章内的事件顺序可在章节时间线上分别调整。</p><label><input type="checkbox" checked={!!v.planned} onChange={e=>set('planned',e.target.checked)}/> 计划情境（尚未确认正文）</label><label>故事排序<input aria-label="故事排序" type="number" step="any" value={v.order} onChange={e=>set('order',e.target.value===''?'':Number(e.target.value))}/></label><label>叙述类型<select aria-label="叙述类型" value={v.narrativeKind} onChange={e=>set('narrativeKind',e.target.value)}>{Object.entries(narrativeKinds).map(([id,label])=><option key={id} value={id}>{label}</option>)}</select></label><MarkdownField label="事件说明" value={v.content} onChange={e=>set('content',e.target.value)}/><PickReferences label="关联角色与世界" items={nodes} value={v.memoryRefs} change={ids=>set('memoryRefs',ids)}/><p className="muted">关联角色仅表示参与这条事件；正式出场仍在“本章资料”确认。</p><PickReferences label="在此首次进入故事的资料" items={nodes} value={v.enteringRefs||[]} change={ids=>set('enteringRefs',ids)}/><p className="muted">这控制阶段图显隐，不能替代正式出场记录。资料可提前完整创建；未指定位置时保持可见。</p><PickReferences label="关联规划" items={plans} name="title" value={v.planningRefs} change={ids=>set('planningRefs',ids)}/>{planningLimit(plans)}{modules.foreshadow&&<PickReferences label="关联伏笔" items={foreshadows} name="title" value={v.foreshadowRefs} change={ids=>set('foreshadowRefs',ids)}/>}<h3>章节呈现与正文依据</h3>{v.chapterRefs.map((r,i)=><div className="structure-entry" key={i}><p>{chapters.find(c=>c.id===r.chapterId)?.title||'已删除章节'} · 版本 {r.revision}</p>{r.evidence&&<blockquote>{r.evidence}</blockquote>}<button onClick={()=>set('chapterRefs',v.chapterRefs.filter((_,j)=>j!==i))}>移除此呈现</button></div>)}<label>章节<select aria-label="事件章节" value={chapterId} onChange={e=>setChapterId(e.target.value)}><option value="">选择章节</option>{chapters.map(c=><option key={c.id} value={c.id}>{c.title}</option>)}</select></label><label>已保存原文（可选）<DocumentTextarea aria-label="事件正文依据" value={quote} onChange={e=>setQuote(e.target.value)}/></label><button disabled={!chapterId} onClick={()=>{const c=chapters.find(c=>c.id===chapterId);set('chapterRefs',[...v.chapterRefs,{chapterId,revision:c.revision,evidence:quote}]);setQuote('');}}>添加章节呈现</button></div><SaveBar dirty={dirty||!initial.id} busy={busy} error={error||cacheError} invalid={!Number.isFinite(v.order)?'填写明确排序':null} onSave={save} label="保存事件"/>{initial.id&&<><WritingHistory current={v} {...{call,novelId,busy,run,dirty,chapters}} collection="events" id={initial.id} revision={base.revision} restored={saved}/><button className="danger" disabled={busy||initial.deleted} onClick={async()=>{if(await confirm(dirty?'删除此事件并放弃当前编辑草稿？历史仍可恢复。':'删除此事件？历史仍可恢复，关联关系变化不再应用于当前关系。'))run(async()=>{setError('');try{await write('writing.event.delete',{novelId,id:initial.id,expectedRevision:base.revision,confirmed:true,reason:'作者删除时间线事件'});accept(base);saved();}catch(e){setError(e.message);throw e;}});}}>删除事件</button></>}</Modal>;
}
function planningLimit(plans){return plans.length>=200?<p className="muted">这里列出前 200 条规划。更多规划可通过 AI 按 ID 关联。</p>:null;}
export function RelationshipChanges({call,novelId,tick,run,busy,onEvent,onMemory}){
 const [editing,setEditing]=useState(null),[poll,setPoll]=useState(0),[includeDeleted,setIncludeDeleted]=useState(false);
 useEffect(()=>{const timer=setInterval(()=>{if(!document.hidden)setPoll(n=>n+1);},5000);return()=>clearInterval(timer);},[]);
 const resource=useResource(()=>Promise.all([call('writing.relationshipChange.list',{novelId,includeDeleted}),call('writing.event.list',{novelId}),call('edge.list',{novelId}),call('graph.list',{novelId})]),[call,novelId,includeDeleted,tick,poll]);
 const [changes=[],events=[],edges=[],nodes=[]]=resource.value||[];
 return <section><div className="row"><h3 className="grow">关系变化记录</h3><button disabled={busy||!events.length||!edges.length} onClick={()=>setEditing({eventId:'',edgeId:'',value:{name:'',content:'',category:'other',style:'solid',active:true},revision:0})}>＋ 关系变化</button></div><label className="timeline-deleted-toggle"><input type="checkbox" checked={includeDeleted} onChange={e=>setIncludeDeleted(e.target.checked)}/> 显示已移除变化，查看历史恢复</label><p className="muted">先在设定中建立基础关系，再选择具体事件记录变化。基础、最新或指定事件的关系图在“设定 → 画布”查看。</p><ResourceState resource={resource}>{!changes.length&&<p>尚无关系变化。</p>}{changes.map(c=><div key={c.id} className="structure-entry relation-change" style={{borderLeftColor:relationColor(c.value)}}><div className="row"><button onClick={()=>onEvent(c.eventId)}>{c.eventTitle}</button><small>{c.storyTime}{c.deleted||c.excluded?' · 已移出当前关系':''}</small><button onClick={()=>setEditing(c)}>编辑变化</button></div><p><button onClick={()=>onMemory(c.from)}>{nodes.find(n=>n.id===c.from)?.name||'已删除资料'}</button> → <button onClick={()=>onMemory(c.to)}>{nodes.find(n=>n.id===c.to)?.name||'已删除资料'}</button></p><strong>{c.value.active?(relationName(c.value)||'未命名关系'):'此阶段关系结束'}</strong><MarkdownText text={c.value.content}/></div>)}</ResourceState>{editing&&<ChangeEditor key={editing.id||'new'} {...{call,novelId,run,busy,events,edges,nodes}} initial={editing} close={()=>setEditing(null)} saved={()=>{setEditing(null);setPoll(n=>n+1);}}/>}</section>;
}
export function ChangeEditor({call,novelId,run,busy,events,edges,nodes,initial,close,saved}){
 const write=useWritingRequest(call),{confirm}=useDialog(),{value:v,base,change,accept,dirty,cacheError}=useDraft(`${novelId}:relationship-change:${initial.id||'new'}`,initial),[error,setError]=useState('');
 const set=(key,value)=>change(old=>({...old,[key]:value})),state=(key,value)=>set('value',{...v.value,[key]:value});
 const save=()=>run(async()=>{setError('');try{const result=await write(initial.id?'writing.relationshipChange.update':'writing.relationshipChange.create',{novelId,id:initial.id,expectedRevision:base.revision,value:v,confirmed:true,reason:'作者记录事件关系变化'});accept(initial.id?result:initial);saved();}catch(e){setError(e.message);throw e;}});
 return <Modal title="编辑关系变化" close={close} className="chapter-materials-modal"><div className="structure-form"><label>具体事件<select aria-label="关系变化事件" value={v.eventId} onChange={e=>set('eventId',e.target.value)}><option value="">选择事件阶段</option>{events.map(e=><option value={e.id} key={e.id}>{e.storyDate||e.storyTime} · {e.planned?'计划 · ':''}{e.title}</option>)}</select></label><label>基础关系<select aria-label="变化的基础关系" value={v.edgeId} onChange={e=>{const edge=edges.find(x=>x.id===e.target.value);change(old=>({...old,edgeId:e.target.value,value:{...old.value,name:edge?.name||'',content:edge?.content||'',typeId:edge?.typeId??null,category:edge?.category||'other',style:edge?.style||'solid'}}));}}><option value="">选择关系</option>{edges.map(e=><option value={e.id} key={e.id}>{nodes.find(n=>n.id===e.from)?.name} → {nodes.find(n=>n.id===e.to)?.name} · {e.name||'未命名'}</option>)}</select></label><label>关系名称（未选字段时显示）<input aria-label="阶段关系名称" value={v.value.name} onChange={e=>state('name',e.target.value)}/></label><RelationshipTypePicker {...{call,novelId,busy}} value={v.value.typeId} onChange={typeId=>state('typeId',typeId)}/><label>线型<select aria-label="阶段关系线型" value={v.value.style} onChange={e=>state('style',e.target.value)}>{Object.entries(relationStyles).map(([id,label])=><option value={id} key={id}>{label}</option>)}</select></label><label>此阶段关系<select aria-label="阶段关系是否存在" value={String(v.value.active)} onChange={e=>state('active',e.target.value==='true')}><option value="true">存在</option><option value="false">结束／暂时不存在</option></select></label><MarkdownField label="变化说明" aria-label="关系变化说明" value={v.value.content} onChange={e=>state('content',e.target.value)}/></div><SaveBar dirty={dirty||!initial.id} busy={busy} error={error||cacheError} invalid={!v.edgeId||!v.eventId?'请选择基础关系和具体事件':null} onSave={save} label="保存关系变化"/>{initial.id&&<><WritingHistory current={v} {...{call,novelId,busy,run,dirty}} collection="relationshipChanges" id={initial.id} revision={base.revision} restored={saved}/><button className="danger" disabled={busy||dirty||initial.deleted} onClick={async()=>{if(await confirm('移除此变化记录？原始基础关系保留。'))run(async()=>{setError('');try{await write('writing.relationshipChange.delete',{novelId,id:initial.id,expectedRevision:base.revision,confirmed:true,reason:'作者移除关系变化'});saved();}catch(e){setError(e.message);throw e;}});}}>移除此变化</button></>}</Modal>;
}
